; boot.s -- PHYSICS boot sector + fast loader (track 0, physical sectors 0,2,4,6)
; Regenerated by tools/gen.py from the original disk; see README.md.
; Assembles to 1024 bytes: page 0 = T0 phys 0, page 1 = phys 2, 2 = phys 4, 3 = phys 6.

        .setcpu "6502"
        .include "hw.inc"
        .include "zp_boot.inc"

; high-bit ASCII string (normal video on the text screen)
.macro  hiasc str
        .repeat .strlen(str), I
        .byte   .strat(str, I) | $80
        .endrepeat
.endmacro
; inverse-video string (character & $3F)
.macro  invtxt str
        .repeat .strlen(str), I
        .byte   .strat(str, I) & $3F
        .endrepeat
.endmacro

        .segment "BOOT"
        .org    $0800

;---------------------------------------------------------------------------
; BOOT SECTOR (track 0, sector 0) and the fast loader it pulls in.
;
; The Disk II boot PROM reads T0/S0 to $0800 and jumps to $0801 with
; X = slot*16.  The first byte ($01) is the customary sector count.
;
; boot_entry re-enters the PROM's read-sector routine ($Cn5C) three times
; to load physical sectors 2, 4 and 6 of track 0 into $0900, $0A00 and
; $0B00 (DOS-order logical sectors 14, 13, 12).  It then copies the four
; pages $0800-$0BFF to $9000-$93FF and continues there, freeing $0800 for
; the program itself.
;---------------------------------------------------------------------------
boot_nsect:
        .byte   $01
boot_entry:
        lda  prom_bufhi                 ; PROM leaves the next buffer page in $27
        cmp  #$09
        bne  boot_next                  ; first entry ($27=9): build the PROM vector
        txa
        lsr a
        lsr a
        lsr a
        lsr a
        ora  #$C0
        sta  prom_vec+1
        lda  #$5C                       ; $Cn5C = PROM read-sector entry
        sta  prom_vec
        lda  prom_bufhi
boot_next:
        cmp  #$0C                       ; four pages loaded?
        beq  relocate
        sec
        sbc  #$08
        asl a
        sta  prom_sector
        ldx  prom_slot16
        jmp  (prom_vec)                 ; PROM reads it and comes back to $0801

;---------------------------------------------------------------------------
; relocate -- still running at $0825: copy $0800-$0BFF to $9000-$93FF,
; then continue in the copy.
;---------------------------------------------------------------------------
relocate:
        ldy  #$00
L0827:
        lda  $0800,y
        sta  $9000,y
        lda  $0900,y
        sta  $9100,y
        lda  $0A00,y
        sta  $9200,y
        lda  $0B00,y
        sta  $9300,y
        iny
        bne  L0827
        jmp  loader

;---------------------------------------------------------------------------
; loader -- read the program described by load_table with a
; custom track-at-a-time RWTS, drawing a progress screen as it goes.
;
; For each 5-byte load_table entry (first track, number of tracks, first
; page, aux flag, sectors on the last track) it seeks to each track and
; reads sectors in whatever order they pass under the head; PHYSICAL
; sector n of a track goes to page (first page + 16*track index + n).
; When the table's 0 terminator is reached the motor is turned off and
; control passes to the program at $0800.
;---------------------------------------------------------------------------
        .org    $9045            ; from here on we run in the $9000 copy
loader:
        stx  prom_slot16
        lda  #$00
        sta  ld_htrack
        sta  ld_dst
        sta  ld_entry
        sta  ld_ticks
        sta  ld_secs
        sta  ld_lastsec
        sta  ld_trkcount
        sta  ld_done
        jsr  draw_screen
next_entry:
        ldx  ld_entry
        lda  load_table,x
        bne  L9066
        jmp  loader_done
L9066:
        sta  ld_track
        lda  load_table+$01,x
        sta  ld_ntracks
        lda  load_table+$02,x
        sta  ld_page
        lda  load_table+$03,x
        sta  ld_aux
        lda  load_table+$04,x
        sta  ld_lastcnt
next_track:
        inc  ld_trkcount
        jsr  seek_track
        lda  #$10
        ldy  ld_ntracks
        cpy  #$01                       ; last track of the entry?
        bne  L908B
        lda  ld_lastcnt
L908B:
        sta  ld_want
        sta  ld_left
        ldx  #$0F
build_map:
        lda  #$00
        cpx  ld_want
        bcs  L9099
        lda  #$01
L9099:
        sta  ld_secmap,x
        dex
        bpl  build_map
read_loop:
        jsr  read_one
        lda  ld_left
        bne  read_loop
        lda  ld_page
        clc
        adc  #$10
        sta  ld_page
        inc  ld_track
        dec  ld_ntracks
        beq  L90B5
        jmp  next_track
L90B5:
        lda  ld_entry
        clc
        adc  #$05
        sta  ld_entry
        jmp  next_entry
loader_done:
        ldx  prom_slot16
        lda  MOTOROFF,x
        jmp  boot_nsect                 ; run the program

;---------------------------------------------------------------------------
; seek_track -- step the head to track ld_track (one half-track at a
; time with the monitor WAIT delay) and charge the move to the
; elapsed-time accumulator.
;---------------------------------------------------------------------------
seek_track:
        lda  ld_track
        asl a
        sta  ld_tmp2
        cmp  ld_htrack
        beq  L910A
L90D0:
        jsr  phase_y
        lda  PHASE0OFF,y                ; phase off (current)
        lda  ld_htrack
        cmp  ld_tmp2
        beq  L90F2
        bcc  L90E2
        dec  ld_htrack
        bcs  L90E4
L90E2:
        inc  ld_htrack
L90E4:
        jsr  phase_y
        lda  PHASE0ON,y                 ; phase on (next)
        lda  #$56
        jsr  WAIT                       ; ~1.3 ms
        jmp  L90D0
L90F2:
        jsr  phase_y
        lda  PHASE0ON,y
        lda  #$60
        jsr  WAIT
        jsr  phase_y
        lda  PHASE0OFF,y
        lda  ld_ticks                   ; release the phase
        clc
        adc  #$03
        sta  ld_ticks
L910A:
        rts

;---------------------------------------------------------------------------
; phase_y -- Y = slot*16 + 2*(half-track & 3): the phase switch offset.
;---------------------------------------------------------------------------
phase_y:
        lda  ld_htrack
        and  #$03
        asl a
        clc
        adc  prom_slot16
        tay
        rts

;---------------------------------------------------------------------------
; read_one -- read the next address field that passes; if it belongs to
; this track and its sector is still wanted, read + decode the sector into
; its page.  Every address field also advances the elapsed-time clock by
; the number of sector times that went by.
;---------------------------------------------------------------------------
read_one:
        ldx  prom_slot16
        jsr  read_address
        bcs  tick_clock
        lda  ld_addr_sec                ; sector times elapsed since the last address field
        sec
        sbc  ld_lastsec
        and  #$0F
        bne  L9127
        lda  #$10
L9127:
        clc
        adc  ld_ticks
        sta  ld_ticks
        lda  ld_addr_sec
        sta  ld_lastsec
        lda  ld_addr_trk
        cmp  ld_track
        bne  tick_clock
        ldy  ld_addr_sec
        cpy  #$10
        bcs  tick_clock
        lda  a:ld_secmap,y
        beq  tick_clock
        tya
        clc
        adc  ld_page
        sta  ld_dst+1
        jsr  read_data
        bcs  tick_clock
        lda  ld_aux                     ; aux write?
        beq  L9153
        sta  RAMWRTON                   ; RAMWRT on
L9153:
        jsr  post_nibble
        sta  RAMWRTOFF                  ; RAMWRT off
        ldy  ld_addr_sec
        lda  #$00
        sta  a:ld_secmap,y
        dec  ld_left
        inc  ld_done
tick_clock:
        lda  ld_ticks
        cmp  #$50                       ; 80 sector times = 1 second (5 rev/s)
        bcc  L9176
        sbc  #$50
        sta  ld_ticks
        lda  ld_secs
        cmp  #$63
        bcs  L9176
        inc  ld_secs
L9176:
        jmp  show_status

;---------------------------------------------------------------------------
; draw_screen -- clear text page 1, print the text records, draw the
; progress-bar brackets and the "of nn" total.
;---------------------------------------------------------------------------
draw_screen:
        ldy  #$00
        lda  #$A0
L917D:
        sta  $0400,y
        sta  $0500,y
        sta  $0600,y
        sta  $0700,y
        iny
        bne  L917D
        lda  #<screen_text
        sta  ld_txt
        lda  #>screen_text
        sta  ld_txt+1
next_record:
        ldy  #$00
        lda  (ld_txt),y
        beq  draw_bar
        sta  txt_dst
        iny
        lda  (ld_txt),y
        sta  txt_dst+1
        ldx  #$00
L91A5:
        iny
        lda  (ld_txt),y
        beq  L91B0
txt_dst := * + 1
        sta  $FFFF,x                    ; self-modified: target address
        inx
        bne  L91A5
L91B0:
        tya
        sec
        adc  ld_txt
        sta  ld_txt
        bcc  next_record
        inc  ld_txt+1
        bne  next_record
draw_bar:
        ldy  #$03
        lda  #$DB                       ; '['
        sta  $06A8,y
        ldy  bar_width
        iny
        iny
        iny
        iny
        lda  #$DD
        sta  $06A8,y
        lda  total_tracks
        ldy  #$0F
        jsr  print_dec2_r4

;---------------------------------------------------------------------------
; show_status -- refresh "Track nn", "Pages left nn",
; "Elapsed nn seconds" and the progress bar.
;---------------------------------------------------------------------------
show_status:
        lda  ld_trkcount
        ldy  #$09
        jsr  print_dec2_r4
        lda  ld_left
        ldy  #$23
        jsr  print_dec2_r4
        lda  #$A8
        sta  ld_scr
        lda  #$05
        sta  ld_scr+1
        lda  ld_secs
        ldy  #$0B
        jsr  print_dec2
        lda  ld_done
        clc
        adc  #$07
        ror a
        lsr a
        lsr a
        sta  ld_tmp2
        ldy  #$00
L9200:
        lda  #$20
        cpy  ld_tmp2                    ; inverse space = filled
        bcc  L9208
        lda  #$AE                       ; '.' = empty
L9208:
        sta  $06AC,y
        iny
        cpy  bar_width
        bcc  L9200
        rts

;---------------------------------------------------------------------------
; print_dec2_r4 -- print A (0-99) as two digits at $04A8+Y.
;---------------------------------------------------------------------------
print_dec2_r4:
        ldx  #$A8
        stx  ld_scr
        ldx  #$04
        stx  ld_scr+1

;---------------------------------------------------------------------------
; print_dec2 -- print A (0-99) as two high-bit ASCII digits at (ld_scr)+Y.
;---------------------------------------------------------------------------
print_dec2:
        ldx  #$B0
L921C:
        cmp  #$0A
        bcc  L9225
        sbc  #$0A
        inx
        bne  L921C
L9225:
        pha
        txa
        sta  (ld_scr),y
        pla
        iny
        ora  #$B0
        sta  (ld_scr),y
        rts

;---------------------------------------------------------------------------
; Text records: target address (lo, hi), screen bytes, $00.
; A $00 in place of an address ends the list.
;---------------------------------------------------------------------------
screen_text:
        .byte   <$058A, >$058A           ; text row 3, column 10: inverse title
        invtxt  " P H Y S I C S "
        .byte   0
        .byte   <$0708, >$0708           ; row 6, column 8
        hiasc   "Loading, please wait..."
        .byte   0
        .byte   <$04AB, >$04AB           ; row 9, column 3 (numbers at $04B1, $04B7)
        hiasc   "Track    of"
        .byte   0
        .byte   <$04C0, >$04C0           ; row 9, column 24 (number at $04CB)
        hiasc   "Pages left"
        .byte   0
        .byte   <$05AB, >$05AB           ; row 11, column 3 (number at $05B3)
        hiasc   "Elapsed    seconds"
        .byte   0
        .byte   0                        ; end of records
        .byte   0                        ; (unused)

;---------------------------------------------------------------------------
; read_address -- wait for D5 AA 96, decode the 4&4 volume/track/sector/
; checksum into $10-$13.  C=0 if the checksum and the DE epilogue are good.
;---------------------------------------------------------------------------
read_address:
        lda  Q6L,x
        bpl  read_address
L9293:
        cmp  #$D5
        bne  read_address
L9297:
        lda  Q6L,x
        bpl  L9297
        cmp  #$AA
        bne  L9293
L92A0:
        lda  Q6L,x
        bpl  L92A0
        cmp  #$96
        bne  L9293
        ldy  #$00
        sty  ld_tmp2
L92AD:
        lda  Q6L,x
        bpl  L92AD
        sec
        rol a
        sta  ld_tmp3
L92B6:
        lda  Q6L,x
        bpl  L92B6
        and  ld_tmp3
        sta  a:ld_addr,y
        eor  ld_tmp2
        sta  ld_tmp2
        iny
        cpy  #$04
        bne  L92AD
        lda  ld_tmp2
        bne  L92D8
L92CD:
        lda  Q6L,x
        bpl  L92CD
        cmp  #$DE
        bne  L92D8
        clc
        rts
L92D8:
        sec
        rts

;---------------------------------------------------------------------------
; read_data -- find D5 AA AD within 32 nibbles, read the 342 6&2
; nibbles (86 to $A0-$F5 backwards, 256 to $0200) XOR-chained through
; denib_tab.  C=0 on a good checksum + DE epilogue.
;---------------------------------------------------------------------------
read_data:
        ldy  #$20
L92DC:
        dey
        beq  L9337
L92DF:
        lda  Q6L,x
        bpl  L92DF
        cmp  #$D5
        bne  L92DC
L92E8:
        lda  Q6L,x
        bpl  L92E8
        cmp  #$AA
        bne  L92DC
L92F1:
        lda  Q6L,x
        bpl  L92F1
        cmp  #$AD
        bne  L92DC
        ldy  #$56
        lda  #$00
L92FE:
        dey
        sty  ld_tmp
L9301:
        ldy  Q6L,x
        bpl  L9301
        eor  denib_tab-$96,y
        ldy  ld_tmp
        sta  a:ld_aux2,y
        bne  L92FE
L9310:
        sty  ld_tmp
L9312:
        ldy  Q6L,x
        bpl  L9312
        eor  denib_tab-$96,y
        ldy  ld_tmp
        sta  $0200,y
        iny
        bne  L9310
L9322:
        ldy  Q6L,x
        bpl  L9322
        eor  denib_tab-$96,y
        bne  L9337
L932C:
        lda  Q6L,x
        bpl  L932C
        cmp  #$DE
        bne  L9337
        clc
        rts
L9337:
        sec
        rts

;---------------------------------------------------------------------------
; post_nibble -- merge the 2-bit and 6-bit halves into 256 bytes at (ld_dst).
;---------------------------------------------------------------------------
post_nibble:
        ldy  #$00
        ldx  #$56
L933D:
        dex
        bpl  L9342
        ldx  #$55
L9342:
        lda  $0200,y
        lsr  ld_aux2,x
        rol a
        lsr  ld_aux2,x
        rol a
        sta  (ld_dst),y
        iny
        bne  L933D
        rts

;---------------------------------------------------------------------------
; Loader parameters.  load_table entries:
;   first track, track count, first page, aux flag, sectors on last track
;---------------------------------------------------------------------------
total_tracks:
        .byte   $09
bar_width:
        .byte   $0E
load_table:
;               trk  n  page aux last
        .byte   $01,$02,$20,$00,$10      ; T1-T2   -> $2000-$3FFF  HGR background
        .byte   $03,$02,$60,$00,$0E      ; T3-T4   -> $6000-$7DFF  tables + box art
        .byte   $05,$01,$94,$00,$07      ; T5      -> $9400-$9AFF  box/dirty-rect code
        .byte   $06,$02,$A0,$00,$01      ; T6-T7.0 -> $A000-$B0FF  sprites (copied to LC $D000)
        .byte   $08,$02,$08,$00,$05      ; T8-T9.4 -> $0800-$1CFF  main program
        .byte   $00                      ; end
        .res    $29, $00

;---------------------------------------------------------------------------
; denib_tab -- 6&2 disk-byte -> 6-bit value, indexed by the disk byte
; ($96-$FF).  The code addresses it as denib_tab-$96, i.e. $9300.
;---------------------------------------------------------------------------
denib_tab:
        .byte   $00,$01,$00,$00,$02,$03,$00,$04
        .byte   $05,$06,$00,$00,$00,$00,$00,$00
        .byte   $07,$08,$00,$00,$00,$09,$0A,$0B
        .byte   $0C,$0D,$00,$00,$0E,$0F,$10,$11
        .byte   $12,$13,$00,$14,$15,$16,$17,$18
        .byte   $19,$1A,$00,$00,$00,$00,$00,$00
        .byte   $00,$00,$00,$00,$00,$1B,$00,$1C
        .byte   $1D,$1E,$00,$00,$00,$1F,$00,$00
        .byte   $20,$21,$00,$22,$23,$24,$25,$26
        .byte   $27,$28,$00,$00,$00,$00,$00,$29
        .byte   $2A,$2B,$00,$2C,$2D,$2E,$2F,$30
        .byte   $31,$32,$00,$00,$33,$34,$35,$36
        .byte   $37,$38,$00,$39,$3A,$3B,$3C,$3D
        .byte   $3E,$3F
